const params = {};
if ($.input.search) params.search = $.input.search;
if ($.input.teamId) params.teamId = $.input.teamId;
if ($.input.limit) params.limit = $.input.limit;
return { params };

const resp = $.steps.listProjects.response || {};
const projects = (resp.projects || []).map(p => ({
  id: p.id || '',
  name: p.name || '',
  framework: p.framework || '',
  updatedAt: p.updatedAt ? new Date(p.updatedAt).toISOString() : '',
  paused: p.paused || false
}));

return {
  projects,
  totalProjects: projects.length,
  nextPage: resp.pagination?.next || null,
  summary: `Found ${projects.length} Vercel project${projects.length === 1 ? '' : 's'}${$.input.search ? ` matching "${$.input.search}"` : ''}`
};
